content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.dashboard-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 16px;
}

.header h1 {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
}

.controls {
  display: flex;
  gap: 8px;
  align-items: center;
}

.btn {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-main);
  padding: 8px 16px;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: var(--border-color);
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.card-unit {
  font-size: 14px;
  font-weight: normal;
  color: var(--text-muted);
}

.card-change {
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
}

.card-change.positive {
  color: var(--success-color);
}

.card-change.negative {
  color: var(--danger-color);
}

.chart-section {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 20px;
}

.chart-container {
  width: 100%;
  height: 350px;
}

@media (max-width: 768px) {
  .dashboard-container {
    padding: 16px;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }

  .chart-container {
    height: 280px;
  }
}

export interface DashboardData {
  month: string;
  sales: number;
  customers: number;
  avgPrice: number;
}

export interface MetricCardProps {
  title: string;
  value: string;
  unit: string;
  change: string;
  isPositive: boolean;
}

import { useState } from 'react';
import { DashboardData } from './types';
import { 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  CartesianGrid 
} from 'recharts';
import './index.css';

const initialData: DashboardData[] = [
  { month: '1月', sales: 4200000, customers: 1400, avgPrice: 3000 },
  { month: '2月', sales: 3800000, customers: 1300, avgPrice: 2923 },
  { month: '3月', sales: 5100000, customers: 1600, avgPrice: 3187 },
  { month: '4月', sales: 4600000, customers: 1500, avgPrice: 3066 },
  { month: '5月', sales: 4900000, customers: 1550, avgPrice: 3161 },
  { month: '6月', sales: 5300000, customers: 1700, avgPrice: 3117 },
];

export default function App() {
  const [data] = useState<DashboardData[]>(initialData);
  const [activeMetric, setActiveMetric] = useState<'sales' | 'customers' | 'avgPrice'>('sales');

  const latest = data[data.length - 1];
  const previous = data[data.length - 2];

  const calcChange = (current: number, prev: number) => {
    const diff = ((current - prev) / prev) * 100;
    return {
      text: `${diff >= 0 ? '+' : ''}${diff.toFixed(1)}%`,
      isPositive: diff >= 0
    };
  };

  const salesChange = calcChange(latest.sales, previous.sales);
  const customersChange = calcChange(latest.customers, previous.customers);
  const avgPriceChange = calcChange(latest.avgPrice, previous.avgPrice);

  return (
    <div className="dashboard-container">
      <header className="header">
        <h1>店舗ダッシュボード</h1>
        <div className="controls">
          <button 
            className="btn" 
            onClick={() => setActiveMetric('sales')}
            style={{ opacity: activeMetric === 'sales' ? 1 : 0.7 }}
          >
            売上表示
          </button>
          <button 
            className="btn" 
            onClick={() => setActiveMetric('customers')}
            style={{ opacity: activeMetric === 'customers' ? 1 : 0.7 }}
          >
            客数表示
          </button>
          <button 
            className="btn" 
            onClick={() => setActiveMetric('avgPrice')}
            style={{ opacity: activeMetric === 'avgPrice' ? 1 : 0.7 }}
          >
            平均単価表示
          </button>
        </div>
      </header>

      <div className="cards-grid">
        <div className="card">
          <span className="card-title">売上</span>
          <div className="card-value">
            {latest.sales.toLocaleString()}
            <span className="card-unit">円</span>
          </div>
          <div className={`card-change ${salesChange.isPositive ? 'positive' : 'negative'}`}>
            {salesChange.isPositive ? '▲' : '▼'} {salesChange.text} (前月比)
          </div>
        </div>

        <div className="card">
          <span className="card-title">客数</span>
          <div className="card-value">
            {latest.customers.toLocaleString()}
            <span className="card-unit">人</span>
          </div>
          <div className={`card-change ${customersChange.isPositive ? 'positive' : 'negative'}`}>
            {customersChange.isPositive ? '▲' : '▼'} {customersChange.text} (前月比)
          </div>
        </div>

        <div className="card">
          <span className="card-title">平均単価</span>
          <div className="card-value">
            {latest.avgPrice.toLocaleString()}
            <span className="card-unit">円</span>
          </div>
          <div className={`card-change ${avgPriceChange.isPositive ? 'positive' : 'negative'}`}>
            {avgPriceChange.isPositive ? '▲' : '▼'} {avgPriceChange.text} (前月比)
          </div>
        </div>
      </div>

      <section className="chart-section">
        <h2 className="chart-title">
          {activeMetric === 'sales' && '月別売上推移'}
          {activeMetric === 'customers' && '月別客数推移'}
          {activeMetric === 'avgPrice' && '月別平均単価推移'}
        </h2>
        <div className="chart-container">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="month" />
              <YAxis />
              <Tooltip 
                formatter={(value: number) => [
                  activeMetric === 'sales' ? `${value.toLocaleString()} 円` :
                  activeMetric === 'customers' ? `${value.toLocaleString()} 人` :
                  `${value.toLocaleString()} 円`,
                  activeMetric === 'sales' ? '売上' :
                  activeMetric === 'customers' ? '客数' : '平均単価'
                ]} 
              />
              <Bar 
                dataKey={activeMetric} 
                fill="#3b82f6" 
                radius={[4, 4, 0, 0]} 
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
}
